example_item.example_item_data:
xml_filename = [tempdir(), 'xmlNodeList_example.xml'];
filewrite(xml_filename, '<list><item>one</item><item>two</item><item>three</item></list>');
doc = xmlread(xml_filename);
nodes = doc.getElementsByTagName('item')
for k = 0:nodes.getLength() - 1
  disp(nodes.item(k).getTextContent());
end
isempty(nodes.item(3))
delete(xml_filename);
